CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TABLE "User" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Archive" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "userId" UUID NOT NULL, "name" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Archive_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Source" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "archiveId" UUID NOT NULL, "kind" TEXT NOT NULL, "stableKey" TEXT NOT NULL, "sha256" VARCHAR(64) NOT NULL, "originalPath" TEXT, "provenance" JSONB, "lifecycle" TEXT NOT NULL DEFAULT 'discovered', "discoveredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "claimedAt" TIMESTAMP(3), "completedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Source_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Snapshot" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "archiveId" UUID NOT NULL, "sourceId" UUID NOT NULL, "sha256" VARCHAR(64) NOT NULL, "provenance" JSONB, "lifecycle" TEXT NOT NULL DEFAULT 'snapshotted', "capturedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Snapshot_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ImportJob" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "archiveId" UUID NOT NULL, "sourceId" UUID NOT NULL, "snapshotId" UUID, "status" TEXT NOT NULL DEFAULT 'discovered', "adapterVersion" TEXT, "outcome" JSONB, "errorClass" TEXT, "startedAt" TIMESTAMP(3), "finishedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ImportJob_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Archive_userId_name_key" ON "Archive"("userId", "name"); CREATE UNIQUE INDEX "Archive_id_userId_key" ON "Archive"("id", "userId");
CREATE UNIQUE INDEX "Source_archiveId_kind_stableKey_key" ON "Source"("archiveId", "kind", "stableKey"); CREATE UNIQUE INDEX "Source_archiveId_id_key" ON "Source"("archiveId", "id"); CREATE INDEX "Source_archiveId_sha256_idx" ON "Source"("archiveId", "sha256");
CREATE UNIQUE INDEX "Snapshot_archiveId_id_key" ON "Snapshot"("archiveId", "id"); CREATE UNIQUE INDEX "Snapshot_archiveId_sourceId_sha256_key" ON "Snapshot"("archiveId", "sourceId", "sha256"); CREATE INDEX "Snapshot_archiveId_sourceId_idx" ON "Snapshot"("archiveId", "sourceId");
CREATE UNIQUE INDEX "ImportJob_archiveId_id_key" ON "ImportJob"("archiveId", "id"); CREATE INDEX "ImportJob_archiveId_status_idx" ON "ImportJob"("archiveId", "status");
ALTER TABLE "Archive" ADD CONSTRAINT "Archive_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Source" ADD CONSTRAINT "Source_archiveId_fkey" FOREIGN KEY ("archiveId") REFERENCES "Archive"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Snapshot" ADD CONSTRAINT "Snapshot_archiveId_fkey" FOREIGN KEY ("archiveId") REFERENCES "Archive"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Snapshot" ADD CONSTRAINT "Snapshot_sourceId_archiveId_fkey" FOREIGN KEY ("sourceId", "archiveId") REFERENCES "Source"("id", "archiveId") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ImportJob" ADD CONSTRAINT "ImportJob_archiveId_fkey" FOREIGN KEY ("archiveId") REFERENCES "Archive"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ImportJob" ADD CONSTRAINT "ImportJob_sourceId_archiveId_fkey" FOREIGN KEY ("sourceId", "archiveId") REFERENCES "Source"("id", "archiveId") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ImportJob" ADD CONSTRAINT "ImportJob_snapshotId_archiveId_fkey" FOREIGN KEY ("snapshotId", "archiveId") REFERENCES "Snapshot"("id", "archiveId") ON DELETE RESTRICT ON UPDATE CASCADE;
